#!/usr/bin/env bash
# SPDX-License-Identifier: GPL-3.0-or-later
#
# Regenerate third_party/pcsx2_files.txt (the import manifest) from a completed build:
# every PCSX2 source we compile, every header those sources include (from the compiler's
# dependency files), the Metal shaders and their includes, and the licence files.
#
#   cmake -S runtime -B build/runtime -G Ninja && cmake --build build/runtime
#   third_party/scripts/update_manifest.sh build/runtime
set -euo pipefail

ROOT="$(cd "$(dirname "$0")/../.." && pwd)"
BUILD="${1:-$ROOT/build/runtime}"
PCSX2="$ROOT/third_party/pcsx2"
OUT="$ROOT/third_party/pcsx2_files.txt"

[[ -f "$BUILD/build.ninja" ]] || { echo "no ninja build in $BUILD" >&2; exit 1; }

{
	# Headers + sources seen by the compiler.
	ninja -C "$BUILD" -t deps | sed -n 's/^    //p'
	# Sources (deps lists only inputs that produced depfiles; add compile inputs explicitly).
	python3 -I -c 'import json,sys; [print(e["file"]) for e in json.load(open(sys.argv[1]))]' \
		"$BUILD/compile_commands.json"
	# Metal shaders and what amalgamate_metal.py inlines.
	find "$PCSX2/pcsx2/GS/Renderers/Metal" -name '*.metal' -o -name 'GSMTL*.h'
	echo "$PCSX2/bin/resources/shaders/common/fxaa.fx"
	echo "$PCSX2/bin/resources/shaders/common/ffx_a.h"
	echo "$PCSX2/bin/resources/shaders/common/ffx_cas.h"
	# Licences.
	echo "$PCSX2/COPYING.GPLv3"
	find "$PCSX2/3rdparty" -maxdepth 2 \( -name 'LICENSE*' -o -name 'LICENCE*' -o -name 'COPYING*' \)
} | python3 -I -c '
import os, sys
root = os.path.realpath(sys.argv[1])
seen = set()
for line in sys.stdin:
    f = line.strip()
    if not f:
        continue
    f = os.path.realpath(f)
    if f.startswith(root + os.sep) and os.path.isfile(f):
        rel = os.path.relpath(f, root)
        if rel != "UPSTREAM_COMMIT":
            seen.add(rel)
print("\n".join(sorted(seen)))
' "$PCSX2" > "$OUT.tmp"

{
	echo "# PCSX2 files imported into third_party/pcsx2 (paths relative to the PCSX2 root)."
	echo "# Generated by third_party/scripts/update_manifest.sh; consumed by import_pcsx2.sh."
	cat "$OUT.tmp"
} > "$OUT"
rm -f "$OUT.tmp"
echo "wrote $OUT ($(grep -vc '^#' "$OUT") files)"
